"""Classification metrics implemented from scratch (no scikit-learn)."""


def _check(y_true, y_pred):
    if len(y_true) != len(y_pred):
        raise ValueError("y_true and y_pred must have the same length")
    if len(y_true) == 0:
        raise ValueError("inputs must not be empty")


def accuracy(y_true, y_pred):
    _check(y_true, y_pred)
    return sum(1 for t, p in zip(y_true, y_pred) if t == p) / len(y_true)


def confusion_matrix(y_true, y_pred, labels=None):
    _check(y_true, y_pred)
    if labels is None:
        labels = sorted(set(y_true) | set(y_pred))
    matrix = {a: {p: 0 for p in labels} for a in labels}
    for t, p in zip(y_true, y_pred):
        if t in matrix and p in matrix[t]:
            matrix[t][p] += 1
    return matrix


def precision_recall_f1(y_true, y_pred, positive_label=1):
    _check(y_true, y_pred)
    tp = sum(1 for t, p in zip(y_true, y_pred) if t == positive_label and p == positive_label)
    fp = sum(1 for t, p in zip(y_true, y_pred) if t != positive_label and p == positive_label)
    fn = sum(1 for t, p in zip(y_true, y_pred) if t == positive_label and p != positive_label)
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
    return precision, recall, f1


def macro_f1(y_true, y_pred):
    _check(y_true, y_pred)
    labels = sorted(set(y_true) | set(y_pred))
    return sum(precision_recall_f1(y_true, y_pred, label)[2] for label in labels) / len(labels)

