import pytest
from metrics import accuracy, confusion_matrix, precision_recall_f1, macro_f1


def test_r1_accuracy_counts_exact_matches():
    assert accuracy([1, 0, 1, 1], [1, 0, 0, 1]) == pytest.approx(0.75)


def test_r2_confusion_matrix_for_binary_labels():
    m = confusion_matrix([1, 0, 1, 0], [1, 1, 0, 0])
    assert m == {0: {0: 1, 1: 1}, 1: {0: 1, 1: 1}}


def test_r3_precision_recall_f1():
    p, r, f1 = precision_recall_f1([1, 1, 0, 0], [1, 0, 1, 0])
    assert (p, r) == (pytest.approx(0.5), pytest.approx(0.5))
    assert f1 == pytest.approx(0.5)


def test_r4_macro_f1_is_perfect_for_perfect_predictions():
    assert macro_f1(["a", "b", "a"], ["a", "b", "a"]) == pytest.approx(1.0)

